const header=document.querySelector('[data-header]');const toggle=document.querySelector('.menu-toggle');const mobile=document.querySelector('.mobile-nav');const onScroll=()=>header?.classList.toggle('scrolled',window.scrollY>24);onScroll();window.addEventListener('scroll',onScroll,{passive:true});toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));mobile?.classList.toggle('open',!open);document.body.classList.toggle('menu-open',!open)});mobile?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{toggle?.setAttribute('aria-expanded','false');mobile.classList.remove('open');document.body.classList.remove('menu-open')}));document.querySelectorAll('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());
